// @pit: {"label": "Adjust two thread tests and the await-in-loop lint in builtin test"}
async ({ workspace: { read, edit } }) => {
  const rep = async (file: string, pairs: [string, string][]) => {
    const r = await read(file, { format: "raw" });
    let c = r.content;
    for (const [a, b] of pairs) {
      if (!c.includes(a)) throw new Error(`${file}: missing ${a.slice(0, 80)}`);
      c = c.replace(a, b);
    }
    await edit(file, { revision: r.revision, changes: [{ kind: "replaceFile", content: c }] });
  };
  const t = await read("src/thread.test.ts", { format: "raw" });
  const i = t.content.indexOf("\t\texpect(systemPromptText(context)).toBe(");
  const seg = t.content.slice(i, i + 200);
  const noneStart = t.content.indexOf(`\tit("says (none) without tools"`);
  const noneSeg = t.content.slice(noneStart, t.content.indexOf("\n\t});\n", noneStart) + 6);
  await rep("src/thread.test.ts", [
    [seg.slice(0, seg.indexOf("DEFAULT_TOOLS,")) + "DEFAULT_TOOLS,", seg.slice(0, seg.indexOf("DEFAULT_TOOLS,")) + `DEFAULT_TOOLS.replace(
					"</tools>",
					"- typescript: Execute TypeScript with explicit function dependencies\\n\\nAdditional tools may be available.\\n</tools>",
				).replace("etc.)\\n\\nAdditional tools may be available.\\n", "etc.)\\n"),`],
    [noneSeg, `\tit("says (none) when no offered tool has a snippet", async () => {
		const custom = defineExtension({ name: "custom", tools: [tool("custom")] });
		const context = await firstRequest([builtin(), custom], {
			tools: { exclude: ["read", "write", "edit", "bash"], hidden: [] },
		});
		expect(toolNames(context)).toStrictEqual(["custom"]);
		const sections = sectionsOf(context);
		expect(sections["tools"]).toBe(
			"<tools>\\n(none)\\n\\nAdditional tools may be available.\\n</tools>",
		);
		expect(sections["rules"]).toBe(\`<rules>\\n\${PI_RULES}\\n</rules>\`);
	});
`],
  ]);
  const b = await read("src/builtin-extension.test.ts", { format: "raw" });
  const s = b.content.indexOf("\t\tconst rendered = new Map<");
  const e = b.content.indexOf("\t\treturn rendered;\n", s) + "\t\treturn rendered;\n".length;
  const c = b.content.slice(0, s) + `\t\tconst rendered = await Promise.all(
			sections.map(async (s) => {
				const text = await s.render(input, BACKGROUND_CONTEXT);
				return [s.key, { text, tag: s.tag }] as const;
			}),
		);
		return new Map(rendered);
` + b.content.slice(e);
  await edit("src/builtin-extension.test.ts", { revision: b.revision, changes: [{ kind: "replaceFile", content: c }] });
  return "ok";
}

// @pit: {"label": "Re-run fix and the thread and builtin tests"}
async ({ shell: { exec } }) => {
  const f = await exec("npm run fix 2>&1 | tail -10", { timeoutMs: 60000 });
  const v = await exec("npx vitest run src/builtin-extension.test.ts src/thread.test.ts 2>&1 | grep -E 'FAIL|Error|Expected|Received|^[-+] |Tests ' | head -60", { timeoutMs: 200000 });
  return { f: f.stdout, v: v.stdout };
}
